809	/// Convert a [`LoadError`] or compatible [`Result`] to a [`SourceDiagnostic`]
810	/// or [`SourceResult`] by adding the [`Loaded`] context.
811	pub trait LoadedWithin {
812	    /// The enriched type that has the context factored in.
813	    type Output;
