950	    }
951	}
952	
953	impl ReportTextPos {
954	    /// Creates a position from a pre-existing range and line-column pair.
955	    pub fn full(range: std::ops::Range<usize>, pair: LineCol) -> Self {
956	        let range = range.start.saturating_as()..range.end.saturating_as();
957	        Self::Full(range, pair)
958	    }
959	
960	    /// Tries to determine the byte range for this position.
961	    fn range(&self, lines: &Lines<String>) -> Option<std::ops::Range<usize>> {
962	        match self {
963	            ReportTextPos::Full(range, _) => {
964	                Some(range.start as usize..range.end as usize)
965	            }
966	            ReportTextPos::Range(range) => Some(range.start as usize..range.end as usize),
967	            &ReportTextPos::LineCol(pair) => {
968	                let i =
969	                    lines.line_column_to_byte(pair.line as usize, pair.col as usize)?;
970	                Some(i..i)
971	            }
972	            ReportTextPos::None => None,
973	        }
974	    }
975	
976	    /// Tries to determine the line/column for this position.
977	    fn line_col(&self, lines: &Lines<String>) -> Option<LineCol> {
978	        match self {
979	            &ReportTextPos::Full(_, pair) => Some(pair),
980	            ReportTextPos::Range(range) => {
981	                let (line, col) = lines.byte_to_line_column(range.start as usize)?;
982	                Some(LineCol::zero_based(line, col))
983	            }
984	            &ReportTextPos::LineCol(pair) => Some(pair),
985	            ReportTextPos::None => None,
986	        }
987	    }
988	
989	    /// Either gets the line/column pair, or tries to compute it from possibly
990	    /// invalid UTF-8 data.
991	    fn try_line_col(&self, bytes: &[u8]) -> Option<LineCol> {
992	        match self {
993	            &ReportTextPos::Full(_, pair) => Some(pair),
994	            ReportTextPos::Range(range) => {
995	                LineCol::try_from_byte_pos(range.start as usize, bytes)
996	            }
997	            &ReportTextPos::LineCol(pair) => Some(pair),
998	            ReportTextPos::None => None,
999	        }
1000	    }
1001	}
1002	
1003	/// A line/column pair.
1004	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
1005	pub struct LineCol {
1006	    /// The 0-based line.
1007	    line: u32,
1008	    /// The 0-based column.
1009	    col: u32,
1010	}
1011	
1012	impl LineCol {
1013	    /// Constructs the line/column pair from 0-based indices.
1014	    pub fn zero_based(line: usize, col: usize) -> Self {
1015	        Self {
1016	            line: line.saturating_as(),
1017	            col: col.saturating_as(),
1018	        }
1019	    }
1020	
1021	    /// Constructs the line/column pair from 1-based numbers.
1022	    pub fn one_based(line: usize, col: usize) -> Self {
1023	        Self::zero_based(line.saturating_sub(1), col.saturating_sub(1))
1024	    }
1025	
1026	    /// Try to compute a line/column pair from possibly invalid UTF-8 data.
1027	    pub fn try_from_byte_pos(pos: usize, bytes: &[u8]) -> Option<Self> {
1028	        let bytes = &bytes[..pos];
1029	        let mut line = 0;
1030	        let line_start = memchr::memchr_iter(b'\n', bytes)
1031	            .inspect(|_| line += 1)
1032	            .last()
1033	            .map(|i| i + 1)
1034	            .unwrap_or(bytes.len());
1035	
1036	        let col = ErrorReportingUtf8Chars::new(&bytes[line_start..]).count();
1037	        Some(LineCol::zero_based(line, col))
1038	    }
1039	
1040	    /// Returns the 0-based line/column indices.
1041	    pub fn indices(&self) -> (usize, usize) {
1042	        (self.line as usize, self.col as usize)
1043	    }
1044	
1045	    /// Returns the 1-based line/column numbers.
1046	    pub fn numbers(&self) -> (usize, usize) {
1047	        (self.line as usize + 1, self.col as usize + 1)
1048	    }
1049	}
1050	
1051	/// Format a user-facing error message for an XML-like file format.
1052	pub fn format_xml_like_error(format: &str, error: roxmltree::Error) -> LoadError {
1053	    let pos = LineCol::one_based(error.pos().row as usize, error.pos().col as usize);
1054	    let message = match error {
1055	        roxmltree::Error::UnexpectedCloseTag(expected, actual, _) => {
1056	            eco_format!(
1057	                "failed to parse {format} (found closing tag '{actual}' instead of '{expected}')"
1058	            )
1059	        }
1060	        roxmltree::Error::UnknownEntityReference(entity, _) => {
1061	            eco_format!("failed to parse {format} (unknown entity '{entity}')")
1062	        }
1063	        roxmltree::Error::DuplicatedAttribute(attr, _) => {
1064	            eco_format!("failed to parse {format} (duplicate attribute '{attr}')")
1065	        }
1066	        roxmltree::Error::NoRootNode => {
1067	            eco_format!("failed to parse {format} (missing root node)")
1068	        }
1069	        err => eco_format!("failed to parse {format} ({err})"),
1070	    };
1071	
1072	    LoadError { text_pos: Some(pos.into()), message }
1073	}
1074	
1075	/// Asserts a condition, generating an internal compiler error with the provided
1076	/// message on failure.
1077	#[track_caller]
1078	pub fn assert_internal(cond: bool, msg: &str) -> HintedStrResult<()> {
1079	    if !cond { Err(internal_error(msg)) } else { Ok(()) }
1080	}
1081	
1082	/// Generates an internal compiler error with the provided message.
1083	#[track_caller]
1084	pub fn panic_internal(msg: &str) -> HintedStrResult<()> {
1085	    Err(internal_error(msg))
1086	}
1087	
1088	/// Adds a method analogous to [`Option::expect`] that raises an internal
1089	/// compiler error instead of panicking.
1090	pub trait ExpectInternal<T> {
1091	    /// Extracts the value, producing an internal error if `self` is `None`.
1092	    fn expect_internal(self, msg: &str) -> HintedStrResult<T>;
1093	}
1094	
1095	impl<T> ExpectInternal<T> for Option<T> {
1096	    #[track_caller]
1097	    fn expect_internal(self, msg: &str) -> HintedStrResult<T> {
1098	        match self {
1099	            Some(val) => Ok(val),
1100	            None => Err(internal_error(msg)),
1101	        }
1102	    }
1103	}
1104	
1105	/// The shared internal implementation of [`assert_internal`],
1106	/// [`panic_internal`] and [`ExpectInternal::expect_internal`].
1107	#[track_caller]
1108	fn internal_error(msg: &str) -> HintedString {
1109	    let loc = std::panic::Location::caller();
1110	    let mut error = error!(
1111	        "internal error: {msg} (occurred at {loc})";
1112	        hint: "please report this as a bug";
1113	    );
1114	
1115	    if cfg!(debug_assertions) {
1116	        let backtrace = Backtrace::capture();
1117	        if backtrace.status() == BacktraceStatus::Captured {
1118	            error.hint(eco_format!("compiler backtrace:\n{backtrace}"));
1119	        } else {
1120	            error.hint("set `RUST_BACKTRACE` to `1` or `full` to capture a backtrace");
1121	        }
1122	    }
1123	
1124	    error
1125	}
